# AI-written variant (not in the book): keep a full-run history too
class FullLossHistory(keras.callbacks.Callback):
    def on_train_begin(self, logs=None):
        self.all_losses = []
    def on_batch_end(self, batch, logs=None):
        self.all_losses.append(logs["loss"])
    def on_train_end(self, logs=None):
        plt.clf()
        plt.plot(self.all_losses)
        plt.savefig("loss_whole_run.png")
